import requests
from bs4 import BeautifulSoup

class NewsScraper:
    def get_latest_news(self, ticker: str, top_n=3) -> str:
        url = f"https://finance.naver.com/item/news_news.naver?code={ticker}"

        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
        }

        try:
            resp = requests.get(url, headers=headers)
            resp.raise_for_status()
            soup = BeautifulSoup(resp.text, "html.parser")

            tbody = soup.select_one("tbody")
            if not tbody:
                return "관련 뉴스 없음."

            rows = tbody.select("tr")
            news_list = []

            for row in rows:
                if "relation_lst" in row.get("class", []):
                    continue # 연관기사 스킵

                title_td = row.select_one("td.title")
                if title_td and title_td.select_one("a"):
                    title = title_td.select_one("a").text.strip()
                    news_list.append(title)

                if len(news_list) >= top_n:
                    break

            if not news_list:
                return "관련 뉴스 없음."

            # 타이틀 리스트를 문자열로 결합
            return "\n".join(f"- {title}" for title in news_list)

        except Exception as e:
            print(f"뉴스 크롤링 오류 ({ticker}): {e}")
            return "오류 발생으로 뉴스 없음."

