import requests
from bs4 import BeautifulSoup


class WebSearcher:
    """네이버 뉴스 검색으로 교차검증용 기사를 수집한다."""

    NAVER_NEWS_SEARCH_URL = "https://search.naver.com/search.naver"
    HEADERS = {
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
            "AppleWebKit/537.36 (KHTML, like Gecko) "
            "Chrome/120.0.0.0 Safari/537.36"
        )
    }

    def search(self, query: str, top_n: int = 5) -> str:
        """키워드로 네이버 뉴스를 검색하여 제목+요약 문자열을 반환한다."""
        html = self._fetch_news_html(query)
        results = self._parse_news_html(html)[:top_n]
        if not results:
            return "관련 뉴스를 찾지 못했습니다."
        lines = []
        for i, r in enumerate(results, 1):
            lines.append(f"[{i}] {r['title']}")
            lines.append(f"    {r['snippet']}")
        return "\n".join(lines)

    def _fetch_news_html(self, query: str) -> str:
        """네이버 뉴스 탭 검색 HTML을 가져온다."""
        params = {"where": "news", "query": query, "sm": "tab_jum"}
        try:
            resp = requests.get(
                self.NAVER_NEWS_SEARCH_URL,
                params=params,
                headers=self.HEADERS,
                timeout=10,
            )
            resp.raise_for_status()
            return resp.text
        except Exception as e:
            print(f"네이버 검색 오류: {e}")
            return ""

    def _parse_news_html(self, html: str) -> list[dict]:
        """HTML에서 기사 제목과 요약을 추출한다."""
        soup = BeautifulSoup(html, "html.parser")
        articles = []
        for item in soup.select("li.bx"):
            title_tag = item.select_one("a.news_tit")
            snippet_tag = item.select_one("div.news_dsc") or item.select_one(
                "a.api_txt_lines.dsc_txt_wrap"
            )
            if not title_tag:
                continue
            title = title_tag.get("title", "") or title_tag.text.strip()
            snippet = snippet_tag.text.strip() if snippet_tag else ""
            articles.append({"title": title, "snippet": snippet})
        return articles

