import os
import yaml
import json
import anthropic


class InferenceEngine:
    """
    4단계 유추 분석 엔진.
    1단계: 사실 검증 — 주장과 증거를 대조하여 사실/거짓/과장 판별
    2단계: 패턴 유추 — 유사한 과거 사례를 찾아 패턴 분석
    3단계: 의도 추론 — 행위 주체의 숨겨진 동기와 향후 전개 추론
    4단계: 기업 전략 유추 — 기업의 궁극적 전략과 로드맵 역추론
    """

    def __init__(self):
        base_dir = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        cred_path = os.path.join(base_dir, "config", "credentials.yaml")

        with open(cred_path, "r", encoding="utf-8") as f:
            cred = yaml.safe_load(f)

        self.client = anthropic.Anthropic(api_key=cred["claude"]["api_key"])
        self.model_name = cred["claude"].get("model", "claude-sonnet-4-20250514")

    def analyze(self, claim: str, evidence: str) -> str:
        """주장+증거를 받아 4단계 유추 분석 리포트를 반환한다."""
        step1 = self._run_llm(self._build_step1_prompt(claim, evidence))
        step2 = self._run_llm(self._build_step2_prompt(claim, step1))
        step3 = self._run_llm(self._build_step3_prompt(claim, step1, step2))
        step4 = self._run_llm(self._build_step4_prompt(claim, step1, step2, step3))
        return self._format_report(claim, step1, step2, step3, step4)

    def extract_search_queries(self, claim: str) -> list[str]:
        """주장에서 교차검증에 필요한 검색 키워드 3개를 자동 추출한다."""
        prompt = f"""다음 주장을 교차검증하기 위해 검색해야 할 키워드를 3개 생성하세요.
각 키워드는 서로 다른 각도에서 검증할 수 있어야 합니다.
(1) 핵심 사실 확인용 (2) 반대 의견/논란 확인용 (3) 배경/맥락 확인용

주장: {claim}

JSON 배열로만 답변하세요. 예: ["키워드1", "키워드2", "키워드3"]"""
        try:
            resp = self.model.generate_content(
                prompt,
                generation_config=genai.types.GenerationConfig(temperature=0.2),
            )
            text = resp.text.strip()
            if text.startswith("```"):
                text = text.split("\n", 1)[1].rsplit("```", 1)[0].strip()
            return json.loads(text)
        except Exception as e:
            print(f"키워드 추출 오류: {e}")
            return [claim]

    # ── 프롬프트 빌더 ──

    def _build_step1_prompt(self, claim: str, evidence: str) -> str:
        return f"""당신은 팩트체커입니다. 주장과 수집된 증거를 대조하여 사실 검증을 수행하세요.

## 분석 대상 주장
{claim}

## 수집된 증거 (뉴스 기사)
{evidence}

## 지시사항
1. 주장에 포함된 핵심 팩트를 하나씩 나열하세요.
2. 각 팩트를 증거와 대조하여 ✅사실 / ⚠️과장 / ❌거짓 / ❓미확인 으로 판정하세요.
3. 증거 간 모순이 있으면 명시하세요.
4. 최종적으로 이 주장의 신뢰도를 높음/중간/낮음으로 평가하세요.

한국어로 답변하세요. "~음", "~함" 체를 사용하세요."""

    def _build_step2_prompt(self, claim: str, step1_result: str) -> str:
        return f"""당신은 패턴 분석 전문가입니다. 아래 사실검증 결과를 바탕으로 유사한 과거 사례를 찾고 패턴을 분석하세요.

## 원래 주장
{claim}

## 1단계 사실검증 결과
{step1_result}

## 지시사항
1. 이 상황과 구조적으로 유사한 과거 사례를 2~3개 찾으세요.
   - 같은 업계/분야 사례 우선, 없으면 다른 분야에서도 가능
   - "어떤 점이 유사한지" 구체적으로 설명
2. 유사 사례들의 공통 패턴을 추출하세요.
   - 사건 전개 순서, 결과, 소요 시간 등
3. 현재 상황이 패턴의 어느 단계에 있는지 평가하세요.

한국어로 답변하세요. "~음", "~함" 체를 사용하세요."""

    def _build_step3_prompt(self, claim: str, step1_result: str, step2_result: str) -> str:
        return f"""당신은 전략 분석가입니다. 사실검증과 패턴분석 결과를 종합하여 행위 주체의 숨겨진 의도를 추론하세요.

## 원래 주장
{claim}

## 1단계 사실검증 결과
{step1_result}

## 2단계 패턴분석 결과
{step2_result}

## 지시사항
1. 이 주장/행위의 **표면적 목적**과 **실제 의도**를 구분하세요.
2. "누가, 무엇을, 왜" 이렇게 했는지 추론하세요.
   - 경제적 동기, 정치적 동기, 시간적 압박 등 고려
3. 가장 가능성 높은 시나리오 3개를 제시하세요:
   - 최선 시나리오 (행위자 의도대로 성공)
   - 기본 시나리오 (가장 높은 확률)
   - 최악 시나리오 (의도 실패)
4. 각 시나리오별 확인할 수 있는 **검증 포인트** (날짜/이벤트)를 제시하세요.

한국어로 답변하세요. "~음", "~함" 체를 사용하세요."""

    def _build_step4_prompt(self, claim: str, step1: str, step2: str, step3: str) -> str:
        return f"""당신은 기업 전략 분석가입니다. 앞선 3단계 분석을 종합하여
이 기업이 궁극적으로 노리는 전략적 큰 그림을 역추론하세요.

## 원래 주장
{claim}

## 1단계 사실검증 결과
{step1}

## 2단계 패턴분석 결과
{step2}

## 3단계 의도추론 결과
{step3}

## 지시사항
1. **전략 역추론**: 이 기업의 개별 행위들(공시, 특허, 계약, 인력, IR)을 하나의 퍼즐로 연결하세요.
   - 이 기업이 3~5년 뒤 어떤 모습이 되려고 하는가?
   - 현재 행보는 그 목표를 향한 어떤 단계인가?

2. **전략 맵**: 기업의 전략을 아래 프레임으로 분석하세요.
   - 표면적 포지셔닝: 시장에 보여주려는 이미지
   - 실제 역량: 기술/인력/재무 기반의 실행 가능성
   - 숨겨진 목표: 표면 뒤에 있는 진짜 전략적 목표
   - 시간축: 단기(1년 이내) / 중기(1-3년) / 장기(3-5년) 로드맵 추정

3. **전략 실현 가능성**: 높음/중간/낮음으로 평가하고 근거를 제시하세요.

4. **투자자/이해관계자가 주시해야 할 핵심 변수** 3가지를 제시하세요.

한국어로 답변하세요. "~음", "~함" 체를 사용하세요."""

    # ── 내부 메서드 ──

    def _run_llm(self, prompt: str) -> str:
        """Gemini API를 호출하여 응답 텍스트를 반환한다."""
        try:
            resp = self.model.generate_content(
                prompt,
                generation_config=genai.types.GenerationConfig(temperature=0.3),
            )
            return resp.text.strip()
        except Exception as e:
            print(f"Gemini 호출 오류: {e}")
            return f"분석 실패: {e}"

    def _format_report(self, claim: str, step1: str, step2: str, step3: str, step4: str) -> str:
        """4단계 결과를 하나의 리포트로 포맷한다."""
        divider = "=" * 60
        thin = "-" * 60
        return f"""{divider}
4단계 유추 분석 리포트
{divider}

분석 대상: {claim}

{thin}
[1단계] 사실 검증
{thin}
{step1}

{thin}
[2단계] 패턴 유추
{thin}
{step2}

{thin}
[3단계] 의도 추론
{thin}
{step3}

{thin}
[4단계] 기업 전략 유추
{thin}
{step4}

{divider}
"""

